var cascadingSlotGameResult=function(){var t=document.querySelector("#result-container"),i=document.querySelector("template"),n=0;return{addTumble:function(){var r=i.content.cloneNode(!0);r.querySelector("span").textContent=n===0?"Base Spin":"Tumbling "+n;t.appendChild(r);n++},submit:function(n){var t,i,r;if(n.preventDefault(),t=[],$(".result-temp").each(function(){var n=$(this).find(".result-raw").val();n!==""&&t.push({Name:$(this).find(".attempt").text(),Value:n})}),i=$("#Nickname").val(),i===undefined){$(".error").removeClass("hidden");return}r={roundName:i,rawResults:t,gameConfigName:$("#GameName").val()};$.ajax({type:"POST",url:"SetCascadingSlotResult",data:r,dataType:"html",success:function(n){$("#set-result").html(n)}})}}}();$(document).ready(function(){cascadingSlotGameResult.addTumble()});